@patch('os.path.isfile')
@patch('os.path.isdir')
def test_find_config_valid_file(mock_isfile, mock_isdir):
    mock_isfile.side_effect = lambda x: x.endswith('.yaml') or x.endswith('.json')
    mock_isdir.return_value = False
    with patch('builtins.open', mock_open(read_data='{"key": "value"}')):
        assert _find_config('/some/path') == ('/some/path', {'key': 'value'})

