import pytest

class YourClass:
    def __init__(self, enabled=True, names=None):
        self.enabled = enabled
        self.names = names if names is not None else []

    def find(self, module_name: str) -> str | None:
        if not self.enabled:
            return None

        module_name, _sep, _submodules = module_name.partition(".")
        module_name = module_name.lower()
        if not module_name:
            return None

        for name in self.names:
            if module_name == name:
                return sections.THIRDPARTY
        return None

class TestFind:
    def test_find_disabled(self):
        obj = YourClass(enabled=False)
        assert obj.find('some.module') is None

    def test_find_empty_module_name(self):
        obj = YourClass(enabled=True)
        assert obj.find('') is None

    def test_find_nonexistent_module(self):
        obj = YourClass(enabled=True)
        obj.names = ['existing_module']
        assert obj.find('nonexistent_module') is None

    def test_find_existing_module(self):
        obj = YourClass(enabled=True)
        obj.names = ['existing_module']
        assert obj.find('existing_module') == sections.THIRDPARTY

